parameters.jsCode:
const raw = $input.first().json.content[0].text;
let posts;
try {
  posts = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { posts = JSON.parse(m[0]); } catch { posts = { linkedin: { post: raw, hashtags: '', char_count: 0 }, twitter: { post: raw.substring(0, 280), hashtags: '' }, instagram: { caption: raw, hashtags: '', hook: '' }, best_time_to_post: '9am IST' }; }
}
return [{ json: { ...posts, generated_at: new Date().toISOString() } }];

